#!/bin/sh
# ============================================================
# AI VIDEO KLIP V4 — SINGLE-FILE OPENWRT INSTALLER
# Storage video/klip: /mnt/sda1/ai-video-klip
# App code: /opt/ai-video-klip
# Supports OpenWrt 24.10 and older (opkg), and 25.12+ (apk).
# ============================================================
set -eu

APP_DIR="/opt/ai-video-klip"
DATA_DIR="/mnt/sda1/ai-video-klip"
TMP="/tmp/ai-video-klip-install"
B64="$TMP/bundle.b64"
BUNDLE="$TMP/bundle.tar.gz"

log(){ echo "[AI-KLIP] $*"; }
fatal(){ echo "[AI-KLIP] ERROR: $*" >&2; exit 1; }

[ "$(id -u)" = "0" ] || fatal "Jalankan sebagai root (SSH root)."
[ -d /mnt/sda1 ] || fatal "/mnt/sda1 belum ada. Mount USB/SD/HDD ke /mnt/sda1 lalu jalankan lagi."
[ -w /mnt/sda1 ] || fatal "/mnt/sda1 tidak writable. Periksa mount/permission."

mkdir -p "$TMP" "$DATA_DIR" \
  "$DATA_DIR/downloads" "$DATA_DIR/clips" \
  "$DATA_DIR/uploads_srt" "$DATA_DIR/uploads_music"

log "Mendeteksi package manager..."
if command -v apk >/dev/null 2>&1; then
  PM=apk
elif command -v opkg >/dev/null 2>&1; then
  PM=opkg
else
  fatal "apk/opkg tidak ditemukan. Ini bukan OpenWrt yang didukung."
fi

install_pkg(){
  if [ "$PM" = apk ]; then
    apk -U add "$@"
  else
    opkg update
    opkg install "$@"
  fi
}

log "Memasang Python, Flask, Requests, yt-dlp, FFmpeg..."
# Package names are OpenWrt package names. If yt-dlp/Flask/Requests are not
# available in the active feed, fallback below uses pip.
install_pkg python3 ffmpeg ffprobe ca-bundle python3-flask python3-requests || {
  log "Paket Python OpenWrt tidak lengkap; mencoba paket minimal + pip..."
  install_pkg python3 ca-bundle ffmpeg ffprobe python3-pip python3-setuptools
  python3 -m pip install --no-cache-dir Flask requests yt-dlp
}

# yt-dlp is sometimes absent from older feeds; install through pip only then.
if ! command -v yt-dlp >/dev/null 2>&1; then
  log "yt-dlp belum tersedia dari feed; memasang via pip..."
  if ! command -v pip3 >/dev/null 2>&1; then
    install_pkg python3-pip python3-setuptools
  fi
  python3 -m pip install --no-cache-dir yt-dlp
fi

command -v python3 >/dev/null 2>&1 || fatal "python3 gagal dipasang."
command -v ffmpeg >/dev/null 2>&1 || fatal "ffmpeg gagal dipasang."
command -v ffprobe >/dev/null 2>&1 || fatal "ffprobe gagal dipasang."
command -v yt-dlp >/dev/null 2>&1 || fatal "yt-dlp gagal dipasang."

log "Mengekstrak aplikasi bawaan installer..."
# The bundle is embedded below. No GitHub repo/file lain diperlukan.
cat > "$B64" <<'__AI_KLIP_B64__'

__AI_KLIP_B64__
base64 -d "$B64" > "$BUNDLE"
rm -rf "$APP_DIR"
mkdir -p /opt
# BusyBox tar supports gzip on standard OpenWrt builds.
tar -xzf "$BUNDLE" -C /opt
mv /opt/ai-video-klip-v4 "$APP_DIR"
chmod +x "$APP_DIR/start.sh"
rm -rf "$TMP"

# Keep configuration on the external disk, not internal flash.
ENV_FILE="$DATA_DIR/.env"
if [ -f "$ENV_FILE" ]; then
  OLD_KEY="$(sed -n 's/^GEMINI_API_KEY=//p' "$ENV_FILE" | head -n1 || true)"
else
  OLD_KEY=""
fi
if [ -z "$OLD_KEY" ]; then
  printf '%s\n' 'GEMINI_API_KEY=' 'DATA_DIR=/mnt/sda1/ai-video-klip' > "$ENV_FILE"
  printf '\n'
  printf 'Masukkan Gemini API key sekarang (Enter untuk skip): '
  read -r KEY || KEY=""
  if [ -n "$KEY" ]; then
    printf '%s\n' "GEMINI_API_KEY=$KEY" 'DATA_DIR=/mnt/sda1/ai-video-klip' > "$ENV_FILE"
    chmod 600 "$ENV_FILE"
  else
    log "Gemini API key belum diisi. Edit: $ENV_FILE"
  fi
else
  log "Gemini API key lama dipertahankan."
fi
chmod 600 "$ENV_FILE" 2>/dev/null || true

# OpenWrt procd service: auto-start after boot.
cat > /etc/init.d/ai-video-klip <<'__INIT__'
#!/bin/sh /etc/rc.common
START=95
STOP=10
USE_PROCD=1

start_service() {
  . /mnt/sda1/ai-video-klip/.env 2>/dev/null || true
  procd_open_instance
  procd_set_param command /usr/bin/python3 /opt/ai-video-klip/app.py
  procd_set_param env DATA_DIR=/mnt/sda1/ai-video-klip GEMINI_API_KEY="${GEMINI_API_KEY:-}"
  procd_set_param cwd /opt/ai-video-klip
  procd_set_param respawn 3600 5 5
  procd_set_param stdout 1
  procd_set_param stderr 1
  procd_close_instance
}
__INIT__
chmod +x /etc/init.d/ai-video-klip
/etc/init.d/ai-video-klip enable
/etc/init.d/ai-video-klip restart || /etc/init.d/ai-video-klip start

IP="$(ubus call system board 2>/dev/null >/dev/null; ip -4 -o addr show 2>/dev/null | awk '$2 != "lo" && $4 ~ /^192\.168\.|^10\.|^172\.(1[6-9]|2[0-9]|3[0-1])\./ {sub(/\/.*$/, "", $4); print $4; exit}')"

printf '\n'
log "=============================================="
log "INSTALLASI AI VIDEO KLIP SELESAI"
log "=============================================="
log "Kode aplikasi : $APP_DIR"
log "Storage video : $DATA_DIR/downloads"
log "Storage klip  : $DATA_DIR/clips"
log "Subtitle      : $DATA_DIR/uploads_srt"
log "Musik         : $DATA_DIR/uploads_music"
log "State         : $DATA_DIR/state.json"
log "Config Gemini : $ENV_FILE"
log "Port          : 5000"
[ -n "$IP" ] && log "Akses          : http://$IP:5000"
log "Cek status    : /etc/init.d/ai-video-klip status"
log "Log           : logread -f | grep -i ai-video"
log "Stop          : /etc/init.d/ai-video-klip stop"
log "Start         : /etc/init.d/ai-video-klip start"
